"""Class 7 Maths Ch 3 - A Peek Beyond the Point (decimals)."""
from g67 import *

SLUG, NAME, CHNO = "Peek_Beyond_the_Point", "A Peek Beyond the Point", 3

def d(x): return Dc(str(x))
def f(x): return fmt(Dc(x).normalize()) if not isinstance(x, str) else x
def S(x): return "$" + fmt(Dc(x).normalize()) + "$"
def dn(q, c, why="", offs=("0.1", "-0.1", "1", "-1", "0.01", "10", "0.5")):
    c = Dc(c); out = []
    for o in offs:
        x = c + Dc(o)
        if x != c and x >= 0 and x not in out: out.append(x)
    return M4(q, fmt(c.normalize()), [fmt(x.normalize()) for x in out[:6]], why)
def rd(x, n): return Dc(x).quantize(Dc(1).scaleb(-n), rounding="ROUND_HALF_UP")
def frac(x):
    f_ = Fr(Dc(x)); return f_
def D(*a): return Dc(str(a[0]))

